def run(cmd, cwd=REPO, check=True, capture=False, env=None):
    print(f"$ {' '.join(cmd)}")
    try:
        result = subprocess.run(
            cmd, cwd=cwd, text=True,
            capture_output=capture, env={**os.environ, **(env or {})} if env else None,
        )
    except OSError as e:
        # 対象コマンド自体が存在しない場合(例: dockerが未インストール)も、
        # 呼び出し元のtry/exceptで確実にロールバックできるようSystemExitに変換する。
        raise SystemExit(f"[ABORT] command not found or failed to start: {' '.join(cmd)} ({e})")
    if check and result.returncode != 0:
        if capture:
            print(result.stdout)
            print(result.stderr, file=sys.stderr)
        raise SystemExit(f"[ABORT] command failed: {' '.join(cmd)}")
    return result


def sha256_of(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def read_env_file(path: Path) -> dict:
    env = {}
    if not path.exists():
        return env
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        k, v = line.split("=", 1)
        env[k.strip()] = v.strip().strip('"').strip("'")
    return env

